  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const result = vatSummary([issued]);

  const entry = result.find((r) => r.rate === firstProduct.vatRate);
  const expectedBase = firstProduct.unitPrice * 100;
  const expectedVAT = Math.round((expectedBase * firstProduct.vatRate) / 100);

  assert.equal(entry.vat, expectedVAT);
});

test('lateFee returns 0 when not overdue (asOf equals dueDate)', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = lateFee(issued, issued.dueDate);

  assert.equal(result, 0);
});

test('lateFee returns 0 when not overdue (asOf before dueDate)', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = lateFee(issued, '2026-01-15');

  assert.equal(result, 0);
});

test('lateFee calculates fee for overdue invoice', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);

  const result = lateFee(issued, '2026-02-01');

  // 10 days overdue, 0.04% per day
  const expectedFee = Math.round((totals.total * 10 * 0.04) / 100);
  assert.equal(result, expectedFee);
});

test('lateFee returns 0 for paid invoice (balance due is 0)', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-01-02' }).value;

  const result = lateFee(paid, '2026-02-01');

  assert.equal(result, 0);
});

test('lateFee uses balance due (respects partial payments)', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const partial = recordPayment(issued, { amount: Math.floor(totals.total / 2), date: '2026-01-02' }).value;

  const fee = lateFee(partial, '2026-02-01');

  // 10 days overdue, 0.04% per day, on remaining balance
  const remainingBalance = totals.total - Math.floor(totals.total / 2);
  const expectedFee = Math.round((remainingBalance * 10 * 0.04) / 100);

  assert.equal(fee, expectedFee);
});

test('lateFee with multiple days overdue', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);

  // 30 days overdue
  const result = lateFee(issued, '2026-03-02');

  const expectedFee = Math.round((totals.total * 30 * 0.04) / 100);
  assert.equal(result, expectedFee);
});

test('lateFee rounds fee correctly', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = lateFee(issued, '2026-01-02');

  // 1 day overdue
  assert.ok(typeof result === 'number');
  assert.ok(result >= 0);
});

test('lateFee with invoices that have discounts', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 20 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);

  const result = lateFee(issued, '2026-02-01');

  // 10 days overdue, 0.04% per day on total (which is after discount)
  const expectedFee = Math.round((totals.total * 10 * 0.04) / 100);
  assert.equal(result, expectedFee);
});

